import unittest


class TestSafeCalculateNormalCases(unittest.TestCase):
    def test_addition_and_precedence(self):
        self.assertAlmostEqual(safe_calculate("2 + 3 * 4"), 14.0)

    def test_parentheses(self):
        self.assertAlmostEqual(safe_calculate("(1 + 2) / 4"), 0.75)

    def test_unary_minus_with_parentheses_and_float(self):
        self.assertAlmostEqual(safe_calculate("-(3 - 5) * 2.5"), 5.0)

    def test_whitespace_ignored(self):
        self.assertAlmostEqual(safe_calculate("  1   +\t2\n* 3 "), 7.0)

    def test_float_literals_and_leading_dot(self):
        self.assertAlmostEqual(safe_calculate(".5 + 1.5"), 2.0)

    def test_unary_plus(self):
        self.assertAlmostEqual(safe_calculate("+5 - +2"), 3.0)

    def test_returns_float_type(self):
        result = safe_calculate("1 + 1")
        self.assertIsInstance(result, float)
        self.assertAlmostEqual(result, 2.0)


class TestSafeCalculateErrors(unittest.TestCase):
    def test_empty_input(self):
        with self.assertRaises(ValueError):
            safe_calculate("")

    def test_whitespace_only_input(self):
        with self.assertRaises(ValueError):
            safe_calculate("   \t\n ")

    def test_division_by_zero(self):
        with self.assertRaises(ZeroDivisionError):
            safe_calculate("2 / 0")

    def test_division_by_zero_expression(self):
        with self.assertRaises(ZeroDivisionError):
            safe_calculate("1 / (3 - 3)")

    def test_invalid_syntax(self):
        for expr in ["1 +", "* 2", "(1 + 2", "1 2", "()", "1 + * 2"]:
            with self.subTest(expr=expr):
                with self.assertRaises(ValueError):
                    safe_calculate(expr)

    def test_lone_dot_is_invalid(self):
        with self.assertRaises(ValueError):
            safe_calculate(".")

    def test_too_long_expression(self):
        with self.assertRaises(ValueError):
            safe_calculate("1 + " * 100 + "1")

    def test_length_boundary_ok(self):
        # Exactly 200 characters should be accepted.
        expr = "1" + " + 1" * 39  # 1 + 39*4 = 157 chars
        expr = expr + " " * (200 - len(expr))
        self.assertAlmostEqual(safe_calculate(expr), 40.0)


class TestSafeCalculateMaliciousInputs(unittest.TestCase):
    def test_import_call_rejected(self):
        with self.assertRaises(ValueError):
            safe_calculate("__import__('os').system('ls')")

    def test_names_rejected(self):
        for expr in ["a + b", "foo(1)", "x", "True", "None"]:
            with self.subTest(expr=expr):
                with self.assertRaises(ValueError):
                    safe_calculate(expr)

    def test_power_operator_rejected(self):
        with self.assertRaises(ValueError):
            safe_calculate("2 ** 3")

    def test_string_literal_rejected(self):
        with self.assertRaises(ValueError):
            safe_calculate("'hello'")

    def test_attribute_access_rejected(self):
        with self.assertRaises(ValueError):
            safe_calculate("(1).__class__")

    def test_non_string_input_rejected(self):
        for bad in [None, 123, 1.5, ["1+1"], {"a": 1}]:
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    safe_calculate(bad)


if __name__ == "__main__":
    unittest.main()

